<template><div class="email-binding"><button v-if="!open" class="secondary-button" :disabled="disabled" @click="open=true">{{ $ui('绑定或更换邮箱') }}</button><form v-else class="store-form" @submit.prevent="challenge?verify():send()"><h3>{{ $ui('绑定或更换邮箱') }}</h3><p class="store-muted">{{ $ui('绑定邮箱用于安全通知和邮箱验证码登录；更换时需要验证原邮箱和新邮箱。') }}</p><label>{{ $ui('新邮箱') }}<input v-model.trim="email" type="email" autocomplete="email" required maxlength="254" :disabled="Boolean(challenge) || busy" /></label><label v-if="!challenge">{{ $ui('当前密码（已设置时必填）') }}<input v-model="password" type="password" autocomplete="current-password" :disabled="busy" /></label><template v-if="challenge"><label>{{ $ui('新邮箱验证码') }}<input v-model.trim="code" inputmode="numeric" autocomplete="one-time-code" required pattern="[0-9]{6}" maxlength="6" /></label><label v-if="requiresOldCode">{{ $ui('原邮箱验证码') }}<input v-model.trim="oldCode" inputmode="numeric" autocomplete="off" required pattern="[0-9]{6}" maxlength="6" /></label><p class="store-muted">{{ $ui('验证码5分钟内有效，请勿向他人提供。') }}</p></template><div class="actions"><button class="primary-button" :disabled="disabled || busy || (!challenge && remaining>0)">{{ $ui(busy?'正在处理…':challenge?'确认绑定':'发送验证码') }}</button><button v-if="challenge" type="button" class="secondary-button" :disabled="busy || remaining>0" @click="resetChallenge">{{ remaining>0?$ui('{0}秒后可重新发送',[remaining]):$ui('重新发送') }}</button><button type="button" class="secondary-button" :disabled="busy" @click="close">{{ $ui('取消') }}</button></div></form><p v-if="error" class="form-error" role="alert">{{ $ui(error) }}</p><p v-if="message" class="form-success" role="status">{{ $ui(message) }}</p></div></template>
<script setup lang="ts">
import {ref,onBeforeUnmount}from'vue';import{platform}from'@/api/platform';import '@/styles/store.css';defineProps<{disabled?:boolean}>();const emit=defineEmits<{bound:[string]}>();const open=ref(false),email=ref(''),password=ref(''),challenge=ref(''),code=ref(''),oldCode=ref(''),requiresOldCode=ref(false),busy=ref(false),remaining=ref(0),error=ref(''),message=ref('');let timer:ReturnType<typeof setInterval>;let active=true;
async function send(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{const result=await platform.requestEmailBinding(email.value,password.value);if(!active)return;challenge.value=result.challenge;requiresOldCode.value=result.requiresOldCode;remaining.value=result.retryAfter;password.value='';clearInterval(timer);timer=setInterval(()=>{remaining.value=Math.max(0,remaining.value-1);if(!remaining.value)clearInterval(timer);},1000);}catch(e){if(active)error.value=e instanceof Error?e.message:'邮箱绑定暂不可用';}finally{if(active)busy.value=false;}}
async function verify(){if(busy.value)return;busy.value=true;error.value='';try{const result=await platform.verifyEmailBinding(challenge.value,code.value,oldCode.value);if(!active)return;close();message.value='邮箱绑定成功。';emit('bound',result.email);}catch(e){if(active)error.value=e instanceof Error?e.message:'邮箱验证码无效或已过期';}finally{if(active)busy.value=false;}}
function resetChallenge(){challenge.value='';code.value='';oldCode.value='';requiresOldCode.value=false;}
function close(){open.value=false;resetChallenge();password.value='';error.value='';}
onBeforeUnmount(()=>{active=false;clearInterval(timer);password.value='';code.value='';oldCode.value='';});
</script>
